import { useEffect, useState } from "react";

interface State<T> {
  data: T | null;
  loading: boolean;
  error: Error | null;
}

export function useFetch<T>(url: string): State<T> {
  const [state, setState] = useState<State<T>>({
    data: null,
    loading: true,
    error: null,
  });

  useEffect(() => {
    const controller = new AbortController();
    let ignore = false;
    setState({ data: null, loading: true, error: null });

    fetch(url, { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then((data: T) => {
        if (!ignore) setState({ data, loading: false, error: null });
      })
      .catch((error: Error) => {
        if (!ignore && error.name !== "AbortError") {
          setState({ data: null, loading: false, error });
        }
      });

    return () => {
      ignore = true;
      controller.abort();
    };
  }, [url]);

  return state;
}

import { useEffect, useState } from "react";

export default function Timer() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    // Functional updater avoids needing `count` in deps (no stale closure).
    const id = setInterval(() => setCount((c) => c + 1), 1000);
    // Cleanup clears the interval before re-run / on unmount -> no leak.
    return () => clearInterval(id);
  }, []);

  return <p>Seconds: {count}</p>;
}

import { useReducer } from "react";

type State = { name: string; email: string; submitting: boolean; error: string | null };
type Action =
  | { type: "field"; field: "name" | "email"; value: string }
  | { type: "submit" }
  | { type: "error"; message: string };

const initial: State = { name: "", email: "", submitting: false, error: null };

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case "field":
      return { ...state, [action.field]: action.value, error: null };
    case "submit":
      return { ...state, submitting: true, error: null };
    case "error":
      return { ...state, submitting: false, error: action.message };
    default:
      return state;
  }
}

export default function SignupForm() {
  const [state, dispatch] = useReducer(reducer, initial);
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        dispatch({ type: "submit" });
      }}
    >
      <input
        value={state.name}
        onChange={(e) => dispatch({ type: "field", field: "name", value: e.target.value })}
      />
      <input
        value={state.email}
        onChange={(e) => dispatch({ type: "field", field: "email", value: e.target.value })}
      />
      <button disabled={state.submitting}>Sign up</button>
      {state.error && <p>{state.error}</p>}
    </form>
  );
}

